/* test_harmonyos.c — HarmonyOS-specific wchar_t URI API round-trip test.
 *
 * Verifies the uriparser wide-char (wchar_t) code path on the OHOS platform.
 * This path is compiled only when the platform's wprintf support is detected
 * (UriConfig.h HAVE_WPRINTF, generated by check_symbol_exists(wprintf wchar.h));
 * a correct round-trip therefore validates a genuine HarmonyOS platform
 * compatibility behavior, not a generic consumer call.
 *
 * It calls real uriparser APIs (uriParseUriW / uriToStringW / uriFreeUriMembersW),
 * parses and recomposes a wide-char URI, and asserts the recomposed output and
 * the parsed host component — not a string-only / compile-only / duplicate test
 * (the existing test_package/test.c exercises the ANSI char API only).
 */
#include <stdio.h>
#include <wchar.h>
#include <string.h>
#include <uriparser/Uri.h>

static int run_wchar_roundtrip(const wchar_t *input) {
    UriParserStateW state;
    UriUriW uri;
    wchar_t buf[1024];
    int chars_written = 0;
    int rc;

    memset(&uri, 0, sizeof(uri));
    state.uri = &uri;

    rc = uriParseUriW(&state, input);
    if (rc != URI_SUCCESS) {
        wprintf(L"FAIL: uriParseUriW rc=%d\n", rc);
        return 1;
    }
    /* The wchar code path parsed the URI; assert the host component exists. */
    if (uri.hostText.first == NULL || uri.hostText.afterLast == NULL ||
        uri.hostText.afterLast - uri.hostText.first <= 0) {
        wprintf(L"FAIL: host component not parsed on wchar path\n");
        uriFreeUriMembersW(&uri);
        return 1;
    }
    wprintf(L"parsed host: %.*ls\n",
            (int)(uri.hostText.afterLast - uri.hostText.first),
            uri.hostText.first);

    /* Re-compose via the wchar API (platform wprintf path). */
    rc = uriToStringW(buf, &uri, (int)(sizeof(buf) / sizeof(buf[0])), &chars_written);
    if (rc != URI_SUCCESS) {
        wprintf(L"FAIL: uriToStringW rc=%d\n", rc);
        uriFreeUriMembersW(&uri);
        return 1;
    }
    if (chars_written <= 0) {
        wprintf(L"FAIL: empty recomposition\n");
        uriFreeUriMembersW(&uri);
        return 1;
    }

    wprintf(L"uriparser HarmonyOS wchar round-trip OK: %ls\n", buf);
    uriFreeUriMembersW(&uri);
    return 0;
}

int main(void) {
    int rc = 0;
    rc |= run_wchar_roundtrip(L"https://example.com/path/to/res?query=1#frag");
    rc |= run_wchar_roundtrip(L"http://user:pass@host.example:8080/a/b");
    if (rc == 0) {
        wprintf(L"[PASSED] uriparser HarmonyOS-specific wchar API test: 2/2 round-trips OK\n");
        return 0;
    }
    return rc;
}
